head.script:
scwin.screenId = "jldfil52100";

///////// 1. 변수 및 선언 영역 /////////

// as-is 흐름 보존 — 활성 폼 캐시(각 업무 함수 진입 시 prtDepoForm 으로 재설정)
scwin.form = null;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 초기화 함수(init_*)를 데이터 의존성 순서로 순차 실행한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam(); // 1) 파라미터 수신 (searchType/uploadCode 등 확보)
        scwin.init_ctxDefaults(); // 2) 미수신 키 기본값 충전 (searchType="0")
        scwin.init_rowCopy(); // 3) 접속자·기첨부파일 문구 표시
        scwin.init_conds(); // 4) searchType·재의무보유 여부 기준 표시 조건 평가
        scwin.init_sessionFill(); // 5) 세션 사용자 토큰(${session.user.*}) 치환
        await scwin.init_pageBody(); // 6) as-is body onload — 업로드 결과 코드 안내(init)
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil52100.onpageload' });
    }
};

/**
 * @method
 * @name init_ctxDefaults
 * @description 파라미터로 오지 않은 dma_pageContext 키에 스펙 기본값(searchType="0")을 충전한다 — 조건 평가(init_conds)보다 먼저 수행.
 * @returns {void}
 * @hidden N
 * @example scwin.init_ctxDefaults();
 */
scwin.init_ctxDefaults = function () {
    const ctxDefaults = { "searchType": "0" };
    const pc = $c.util.getComponent("dma_pageContext");
    if (!pc || !pc.get || !pc.set) { return; }
    for (const key in ctxDefaults) {
        const cur = pc.get(key);
        if (cur === undefined || cur === null || cur === '') {
            pc.set(key, ctxDefaults[key]);
        }
    }
};

/**
 * @method
 * @name init_conds
 * @description searchType(dma_pageContext)·재의무보유 여부(dma_loadDetailList.prtdepoReopnYn) 값으로 업로드/다운로드 영역과 제출·저장 버튼의 표시 조건을 평가한다(공용 $c.util.evalConds) — 진입점에서 1회, 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_conds();
 */
scwin.init_conds = function () {
    const readSearchType = function () {
        return $c.data.readValue("dma_pageContext", "searchType", { ctx: true, label: "searchType" });
    };
    const readReopnYn = function () {
        return $c.data.readValue("dma_loadDetailList", "prtdepoReopnYn", { label: "loadDetailList.prtdepoReopnYn" });
    };
    const binds = [
        { id: "ipt_prtDepoReopnYn", fn: function () { return (readReopnYn() === 'Y'); } },
        { id: "c_otherwise_75", fn: function () { return (!((readReopnYn() === 'Y'))); } },
        { id: "if_searchType", fn: function () { return (readSearchType() === '0'); } },
        { id: "txt_text89", fn: function () { return (readSearchType() === '1'); } },
        { id: "btn_FileDown", fn: function () { return (readSearchType() === '1'); } },
        { id: "if_searchType_3", fn: function () { return (readSearchType() === '2' || readSearchType() === '3'); } },
        { id: "if_searchType_4", fn: function () { return (readSearchType() === '0'); } },
        { id: "txt_text102", fn: function () { return (readSearchType() === '1'); } },
        { id: "btn_FileDown_2", fn: function () { return (readSearchType() === '1'); } },
        { id: "if_searchType_6", fn: function () { return (readSearchType() === '2' || readSearchType() === '3'); } },
        { id: "btn_filePrtDepoWithd", fn: function () { return (readSearchType() === '4'); } },
        { id: "btn_insertPrtDepoWithd", fn: function () { return (readSearchType() === '0'); } },
        { id: "btn_updatePrtDepoWithd", fn: function () { return (readSearchType() === '2'); } },
        { id: "btn_updatePrtDepoWithd_2", fn: function () { return (readSearchType() === '3'); } }
    ];
    $c.util.evalConds(binds);
};

/**
 * @method
 * @name init_rowCopy
 * @description 접속아이디/성명 문구(__rb0)와 기첨부 파일명(btn_FileDown·__rb1·btn_FileDown_2·__rb2)을 세션 정보·dlt_attachList 값으로 복사 표시한다 — 진입점에서 1회, 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 * @example scwin.init_rowCopy();
 */
scwin.init_rowCopy = function () {
    const readAttachNm = function (row) {
        return String($c.data.readValue("dlt_attachList", "attachFileNm", { row: row, silent: true }));
    };
    const rowCopies = [
        {
            childId: "__rb0",
            fn: function () {
                const user = ($c.session && $c.session.getUserInfo && $c.session.getUserInfo()) || {};
                return String(user["usrId"] ?? "") + "/" + String(user["corpUsrNm"] ?? "");
            }
        },
        { childId: "btn_FileDown", fn: function () { return readAttachNm(0); } },
        { childId: "__rb1", fn: function () { return " 기 첨부된 파일 : " + readAttachNm(0); } },
        { childId: "btn_FileDown_2", fn: function () { return readAttachNm(1); } },
        { childId: "__rb2", fn: function () { return " 기 첨부된 파일 : " + readAttachNm(1); } }
    ];
    $c.data.copyRows(rowCopies);
};

/**
 * @method
 * @name init
 * @description 재진입 시 업로드 결과 코드(uploadCode: 0 저장/1 유형 불가/2 크기 초과)와 prtDepoNo 유무를 판정해 저장·업로드 결과 안내를 띄운다(searchType 이 빈값·'0' 이면 통과).
 * @returns {void}
 * @hidden N
 * @example await scwin.init();
 */
scwin.init = async function () {
    const readCtx = function (key) {
        const raw = $c.data.readValue("dma_pageContext", key, { ctx: true, soft: true, label: key });
        const val = String(raw == null ? '' : raw);
        return val.indexOf('$' + '{') >= 0 ? '' : val;
    };
    const uploadCode = readCtx("uploadCode");
    const prtDepoNo = readCtx("prtDepoNo");
    const searchType = readCtx("searchType");
    if (searchType !== '' && searchType !== '0') {
        if (uploadCode === '0') {
            await $c.win.alert('저장되었습니다.');
        } else {
            if (uploadCode === '1') {
                await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
            } else {
                if (uploadCode === '2') {
                    await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                } else {
                    if (prtDepoNo === '') {
                        await $c.win.alert('저장시 오류가 발생하였습니다.');
                    }
                }
            }
        }
    }
};


/**
 * @method
 * @name init_pageBody
 * @description as-is body onload 대응 — 활성 폼(prtDepoForm) 캐시를 설정하고 업로드 결과 안내(init)를 수행한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.init_pageBody();
 */
scwin.init_pageBody = async function () {
    try {
        scwin.form = (document.prtDepoForm || { elements: [] });
        searchType = 'null';
        await scwin.init();

    } catch (_ex) {
        await $c.exception.handleError(_ex, { context: 'jldfil52100.onpageload' });
    }
};

/**
 * @method
 * @name init_sessionFill
 * @description 세션 사용자 결선 — 화면 내 텍스트/입력값의 ${session.user.usrId}·${session.user.corpUsrNm} 토큰을 gcc $c.session.getUserInfo 값으로 치환한다(어휘 session_attribute 2건).
 * @returns {void}
 * @hidden N
 * @example scwin.init_sessionFill();
 */
scwin.init_sessionFill = function () {
    const names = ["usrId", "corpUsrNm"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v;
            try {
                v = $c.session.getUserInfo(names[i]);
            } catch (_e) {
                $c.exception.handleError(_e, { notify: 'none', context: 'jldfil52100' });
                v = undefined;
            }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            const renderRoot = (typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render)
                ? $c.win.getFrame().render
                : document;
            const root = renderRoot.body || renderRoot;
            const doc = root.ownerDocument || root;
            const w = doc.createTreeWalker(root, NodeFilter.SHOW_TEXT);
            let n;
            while ((n = w.nextNode())) {
                if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); }
            }
            const ins = renderRoot.querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) {
                if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); }
            }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터를 dma_pageContext 로 수신한다(공용 $c.data.recvParamData, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫).
 * @returns {void}
 * @hidden N
 * @example scwin.init_recvParam();
 */
scwin.init_recvParam = function () {
    $c.data.recvParamData('dma_pageContext');
};

// 파일 업로드 컨트롤 결선 — __krxFileControl 이 있으면 그것으로, 없으면 렌더 루트에서 id 로 조회한다.
scwin.upd_attachFiles = (typeof __krxFileControl === 'function')
    ? __krxFileControl('upd_attachFiles')
    : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render)
        ? $c.win.getFrame().render
        : document).querySelector('[id="upd_attachFiles"]');

scwin.upd_attachFiles_2 = (typeof __krxFileControl === 'function')
    ? __krxFileControl('upd_attachFiles_2')
    : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render)
        ? $c.win.getFrame().render
        : document).querySelector('[id="upd_attachFiles_2"]');

scwin.upd_attachFiles_3 = (typeof __krxFileControl === 'function')
    ? __krxFileControl('upd_attachFiles_3')
    : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render)
        ? $c.win.getFrame().render
        : document).querySelector('[id="upd_attachFiles_3"]');

scwin.upd_attachFiles_4 = (typeof __krxFileControl === 'function')
    ? __krxFileControl('upd_attachFiles_4')
    : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render)
        ? $c.win.getFrame().render
        : document).querySelector('[id="upd_attachFiles_4"]');


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name btn_findAcptCompany_onclick
 * @description 회사명 검색 버튼 클릭 — 법인 검색 팝업을 연다(scwin.fn_findAcptCompany).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_findAcptCompany_onclick = function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.fn_findAcptCompany();
    } catch (_ex) {
        $c.exception.handleError(_ex, { context: 'jldfil52100.btn_findAcptCompany_onclick' });
    }
};

