/**
 * @method
 * @name ipt_fstPrtDepoShrs_onkeyup
 * @description 최초의무보유 주식수 keyup — 입력값을 천단위 콤마 형식으로 포맷한다($c.num.formatNumber).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onkeyup 바인딩으로 자동 호출)
 */
scwin.ipt_fstPrtDepoShrs_onkeyup = function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
