/**
 * @method
 * @name btn_FileDown_onclick
 * @description 처분신청 공문 기첨부 파일 버튼 클릭 — dlt_attachList 0행의 식별자(의무보유ID·신청 일련번호·파일 일련번호)로 파일을 다운로드한다(scwin.fn_FileDown).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_FileDown_onclick = async function (e) {
    try {
        const ev = e;
        const event = ev;
        const selfEl = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        const prtdepoId = '' + $c.data.readValue("dlt_attachList", "prtdepoId", { row: 0, silent: true }) + '';
        const applSeq = '' + $c.data.readValue("dlt_attachList", "prtdepoWithdApplSeq", { row: 0, silent: true }) + '';
        const fileSeq = '' + $c.data.readValue("dlt_attachList", "attachFileSeq", { row: 0, silent: true }) + '';
        await scwin.fn_FileDown(prtdepoId, applSeq, fileSeq);
    } catch (_ex) {
        await $c.exception.handleError(_ex, { context: 'jldfil52100.btn_FileDown_onclick' });
    }
};

/**
 * @method
 * @name btn_FileDown_2_onclick
 * @description 첨부서류 기첨부 파일 버튼 클릭 — dlt_attachList 1행의 식별자(의무보유ID·신청 일련번호·파일 일련번호)로 파일을 다운로드한다(scwin.fn_FileDown).
