/**
 * @method
 * @name btn_updatePrtDepoWithd_onclick
 * @description [저장] 버튼 클릭(수정, searchType=2) — 처분신청을 updateType=2 로 수정 저장한다(scwin.updatePrtDepoWithd).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (body ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_updatePrtDepoWithd_onclick = async function (e) {
