        return;
    }
    if ('' !== nm) {
        $c.util.getComponent("ipt_shrhdNm").setValue(nm);
    } else {
        await $c.win.alert('선택하신 의무보유자명이 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    if ('' !== shrs) {
        $c.util.getComponent("ipt_fstPrtDepoShrs").setValue(shrs);
    } else {
        await $c.win.alert('선택하신 의무보유주식수가 존재하지 않거나 올바르지 않습니다.\n' + '헬프데스크로 문의바랍니다.');
    }
    $c.util.getComponent("ipt_objKind").setValue(objKind);
};


