/**
 * @method
 * @name checkValue
 * @description 저장 전 필수 입력 검증 — 처분주식수·최종의무보유주식수 입력 여부를 확인하고, 재의무보유 체크 상태에 따라 ipt_prtDepoReopnYn 을 'Y'/'N' 으로 확정하며 'Y' 이면 재의무보유일 입력을 요구한다.
 * @returns {Boolean} 검증 통과 여부(true 통과 / false 중단)
 * @hidden N
 * @example if (await scwin.checkValue() === false) { return; }
 */
scwin.checkValue = async function () {
    scwin.form = (document.prtDepoForm || { elements: [] });
    const withdShrs = $c.util.getComponent('ipt_prtDepoWithdShrs').getValue();
    if ((withdShrs == null ? '' : String(withdShrs)) === '') {
        await $c.win.alert("처분주식수를 입력하십시오.");
        return false;
    }
    const lstShrs = $c.util.getComponent('ipt_lstPrtDepoShrs').getValue();
    if ((lstShrs == null ? '' : String(lstShrs)) === '') {
        await $c.win.alert("최종의무보유주식수를 입력하십시오.");
        return false;
    }
    const reopnYnComp = $c.util.getComponent('ipt_prtDepoReopnYn');
    const reopnYnChecked = (!reopnYnComp || typeof reopnYnComp.getValue !== 'function')
        ? (console.warn('[sdd] .checked 대상 미해결: ipt_prtDepoReopnYn'), false)
        : (reopnYnComp.getValue() != null && String(reopnYnComp.getValue()) !== '');
    if (reopnYnChecked === true) {
        $c.util.getComponent("ipt_prtDepoReopnYn").setValue('Y');
        const reopnDd = $c.util.getComponent('cal_prtDepoReopnDD').getValue();
        if ((reopnDd == null ? '' : String(reopnDd)) === '') {
            await $c.win.alert('재의무보유일을 입력하십시오.');
            return false;
        }
    } else {
        $c.util.getComponent("ipt_prtDepoReopnYn").setValue('N');
    }
    return true;
};


/**
 * @method
 * @name insertPrtDepoWithd
 * @description 처분신청 신규 저장 — 공문·첨부서류 업로드 파일과 필수 입력(checkValue)을 검증한 뒤 확인을 받아 주식수 3필드의 콤마를 제거하고 신규 저장(tx_insertPrtDepoWithd)을 호출한다.
 * @returns {void}
 * @hidden N
 * @example await scwin.insertPrtDepoWithd();
 */
scwin.insertPrtDepoWithd = async function () {
    scwin.form = (document.prtDepoForm || { elements: [] });
    scwin.form.action = '/listInvstg/prtDepo.do';
    $c.util.getComponent('dma_FileDownReq').set('method', 'write');
    const attachFiles = $c.util.getComponent('upd_attachFiles').getValue();
    if ((attachFiles == null ? '' : String(attachFiles)) === '') {
        await $c.win.alert("처분신청 공문 관련 파일을 선택바랍니다.");
        return;
    }
    const attachFiles3 = $c.util.getComponent('upd_attachFiles_3').getValue();
    if ((attachFiles3 == null ? '' : String(attachFiles3)) === '') {
        await $c.win.alert("첨부서류을 선택바랍니다.");
        return;
    }
    if (await scwin.checkValue() === false) {
        return;
    }
    if (await $c.win.confirm('저장하시겠습니까?')) {
        // 주식수 입력 콤마 제거 — fieldEl 해석 대상에 따라 setValue/getValue 또는 value 속성으로 반영
        const unformatField = function (compId, fieldName) {
            const el = $c.util.fieldEl(compId, fieldName);
            if (!el) { return; }
            if (el.setValue && el.getValue) {
                el.setValue(String($c.num.unFormatNumber(el.getValue())));
            } else if (typeof el === "object" && "value" in el) {
                el.value = $c.num.unFormatNumber(el.value);
            }
        };
        unformatField('ipt_fstPrtDepoShrs', 'fstPrtDepoShrs');
        unformatField('ipt_prtDepoWithdShrs', 'prtDepoWithdShrs');
        unformatField('ipt_lstPrtDepoShrs', 'lstPrtDepoShrs');
        await scwin.tx_insertPrtDepoWithd();
    }
};


/**
 * @method
 * @name updatePrtDepoWithd
 * @description 처분신청 수정 저장 — searchType/method 전문을 설정하고 필수 입력(checkValue) 검증·확인 후 주식수 3필드의 콤마를 제거하고 수정 저장(tx_updatePrtDepoWithd)을 호출한다.
 * @param {Number} updateType 수정 유형(2: searchType=2 화면, 3: searchType=3 화면)
 * @returns {void}
 * @hidden N
 * @example await scwin.updatePrtDepoWithd(2);
 */
scwin.updatePrtDepoWithd = async function (updateType) {
    scwin.form = (document.prtDepoForm || { elements: [] });
    const fileDownReq = $c.util.getComponent('dma_FileDownReq');
    fileDownReq.set('searchType', updateType);
    scwin.form.action = '/listInvstg/prtDepo.do';
    fileDownReq.set('method', 'updatePrtDepoWithd');
    if (await scwin.checkValue() === false) {
        return;
    }
    if (await $c.win.confirm('저장하시겠습니까?')) {
        // 주식수 입력 콤마 제거 — fieldEl 해석 대상에 따라 setValue/getValue 또는 value 속성으로 반영
        const unformatField = function (compId, fieldName) {
            const el = $c.util.fieldEl(compId, fieldName);
            if (!el) { return; }
            if (el.setValue && el.getValue) {
                el.setValue(String($c.num.unFormatNumber(el.getValue())));
            } else if (typeof el === "object" && "value" in el) {
                el.value = $c.num.unFormatNumber(el.value);
            }
        };
        unformatField('ipt_fstPrtDepoShrs', 'fstPrtDepoShrs');
        unformatField('ipt_prtDepoWithdShrs', 'prtDepoWithdShrs');
        unformatField('ipt_lstPrtDepoShrs', 'lstPrtDepoShrs');
        await scwin.tx_updatePrtDepoWithd();
    }
};


/**
 * @method
 * @name sendPrtDepoWithd
 * @description 처분신청 제출 — 제출 확인을 받은 뒤 처분신청번호·수정 유형·method 를 전문(dma_FileDownReq)에 설정하고 제출(tx_sendPrtDepoWithd)을 호출한다.
